mapper.select:
SELECT

FROM appointment a
WHERE a.deleted = 0
AND a.status = #{status}
AND a.user_id = #{userId}
AND a.package_id = #{packageId}

    AND EXISTS (SELECT 1 FROM appointment_slot s WHERE s.id = a.slot_id AND s.appoint_date = #{appointDate})

ORDER BY a.create_time DESC, a.id DESC

mapper.update:
UPDATE appointment
SET status = #{status}
WHERE id = #{id} AND deleted = 0
